export const SAMPLE_PUZZLES: Puzzle[] = RAW_PUZZLES;

export function getPuzzleById(id: string): Puzzle | undefined {
  const found = SAMPLE_PUZZLES.find(p => p.id === id);
  if (found) return found;
  // Falls back to data/experimentalPuzzles.ts when present — a separate,
  // non-live test batch reachable by direct ID for manual comparison, but
  // invisible to every campaign-region/daily listing (those only ever read
  // SAMPLE_PUZZLES directly, never this fallback).
  return EXPERIMENTAL_PUZZLES.find(p => p.id === id);
}
